CREATE TYPE "Role" AS ENUM ('ADMIN','MANAGER','EMPLOYEE');
CREATE TYPE "SharePermission" AS ENUM ('VIEW','DOWNLOAD');
CREATE TYPE "AuditAction" AS ENUM ('LOGIN','LOGIN_FAILED','LOGOUT','UPLOAD','DOWNLOAD','VIEW','SHARE','REVOKE','DELETE','ACCESS_DENIED','ROLE_CHANGE');
CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'EMPLOYEE',"department" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Session" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Session_userId_idx" ON "Session"("userId"); CREATE INDEX "Session_expiresAt_idx" ON "Session"("expiresAt");
CREATE TABLE "Document" ("id" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"title" TEXT NOT NULL,"category" TEXT NOT NULL,"originalName" TEXT NOT NULL,"storageName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Document_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Document_storageName_key" ON "Document"("storageName"); CREATE INDEX "Document_ownerId_createdAt_idx" ON "Document"("ownerId","createdAt");
CREATE TABLE "DocumentShare" ("id" TEXT NOT NULL,"documentId" TEXT NOT NULL,"recipientId" TEXT NOT NULL,"permission" "SharePermission" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"revokedAt" TIMESTAMP(3),CONSTRAINT "DocumentShare_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DocumentShare_documentId_recipientId_key" ON "DocumentShare"("documentId","recipientId"); CREATE INDEX "DocumentShare_recipientId_revokedAt_idx" ON "DocumentShare"("recipientId","revokedAt");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"userId" TEXT,"documentId" TEXT,"action" "AuditAction" NOT NULL,"success" BOOLEAN NOT NULL,"ip" TEXT,"details" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt"); CREATE INDEX "AuditLog_userId_createdAt_idx" ON "AuditLog"("userId","createdAt");
ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Document" ADD CONSTRAINT "Document_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "DocumentShare" ADD CONSTRAINT "DocumentShare_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "Document"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DocumentShare" ADD CONSTRAINT "DocumentShare_recipientId_fkey" FOREIGN KEY ("recipientId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_documentId_fkey" FOREIGN KEY ("documentId") REFERENCES "Document"("id") ON DELETE SET NULL ON UPDATE CASCADE;
